import {createNotebook,courseCatalog,validateLibrary,migrateV1,openNotebook,toggleSubject,validCustom} from './notebooks.js?v=5';
import {mean,round,criterionValue,entriesFor,appendGrade,summarize,remainingTarget,parseBulk} from './engine.js?v=5';
const BOJA='https://www.juntadeandalucia.es/boja/2023/104/36';
const PEC='https://www.iesnestoralmendros.es/joomla/images/PDFs/2025-26/PEC_20251112.pdf';
const KEY='brujula-eso-v3';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n===null?'—':round(n).toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2});
let allCatalog,library,catalog,storageError=false,loadFailed=false,state,view='home',selected='mat',period='course',filter='',onlyPending=false,simSubject='mat',simCode='1.1',simValue=8,simTarget=7;

function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function save(){if(loadFailed){toast("Hay una copia local que no se pudo leer. Importa una copia válida para sustituirla; mientras tanto, exporta tus cambios antes de cerrar.");return false}try{localStorage.setItem(KEY,JSON.stringify(library));storageError=false;return true}catch(e){storageError=true;toast('No se puede guardar en este navegador. Exporta una copia antes de cerrar.');return false}}
function active(){return catalog.filter(s=>state.selectedSubjects.includes(s.id)&& (s.id!=='rel'||state.attention==='religion'))}
function averaged(){return active().filter(s=>!state.normalized||s.id!=='rel')}
function syncBook(){state=library.notebooks.find(b=>b.id===library.activeId);catalog=courseCatalog(allCatalog,state)}
function switchBook(course,year){state=openNotebook(library,course,year,allCatalog);syncBook();save();navigate('settings')}
function subject(){return catalog.find(s=>s.id===selected)}
function options(items,value){return items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}
const periods=[['course','Curso · notas acumuladas'],['1','1.ª evaluación'],['2','2.ª evaluación'],['3','3.ª evaluación'],['final','Final · confirmada por el docente']];
const methodName=()=>state.method==='competencies'?'media de competencias':'media de criterios';
function navigate(v,sid){view=v;if(sid)selected=sid;filter='';onlyPending=false;render();window.scrollTo({top:0,behavior:'instant'})}
function frame(content){return `<aside class="sidebar"><div class="brand"><span class="logo">✧</span>brújula<span style="color:#a5b49a">.</span></div><div class="brand-sub">TU CURSO, MÁS CLARO</div><nav class="nav" aria-label="Navegación principal">${[['home','▦','Mi resumen'],['subjects','▤','Mis criterios'],['radar','◎','Radar de mejora'],['sim','⌁','Simulador']].map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''}"><b>${i}</b>${t}</button>`).join('')}<div class="nav-label">TU CUADERNO</div>${[['guide','ⓘ','Cómo se calcula'],['settings','⚙','Ajustes y copias']].map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''}"><b>${i}</b>${t}</button>`).join('')}</nav><div class="school"><span class="eyebrow">${state.course}.º ESO · ANDALUCÍA</span><strong>IES Néstor Almendros</strong><span class="muted">Tomares · Curso ${esc(state.year)}</span><br><small>Cuaderno personal · no oficial</small></div><div class="privacy"><span>◉</span> Tus notas se quedan contigo</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Mi cuaderno &nbsp;/&nbsp; <strong>${esc(({home:'Resumen',subjects:'Criterios',radar:'Radar de mejora',sim:'Simulador',guide:'Cómo se calcula',settings:'Ajustes y copias'})[view])}</strong></div><div class="controls"><span class="chip"><span class="dot">●</span> ${storageError?'Guardado no disponible':'Solo en este navegador'}</span><select id="period" aria-label="Periodo de las notas">${options(periods,period)}</select><select id="course" aria-label="Curso de ESO">${options([1,2,3,4].map(n=>[String(n),`${n}.º ESO`]),String(state.course))}</select></div></header>${storageError?'<div class="status-error">No se ha podido cargar o guardar tu cuaderno. No sobrescribiremos una copia dañada automáticamente. Exporta los datos disponibles y revisa el almacenamiento del navegador.</div>':''}${content}<footer class="footer"><span>Hecho para entender tus notas, criterio a criterio.</span><span><a href="./fuentes.html">Fuentes: BOJA, BOE y PEC ↗</a></span></footer></main>`}
function stats(){const summaries=averaged().map(s=>summarize(s,state,period)),known=summaries.filter(s=>s.value!==null);return {summaries,known,global:mean(known.map(s=>round(s.value))),done:summaries.reduce((n,s)=>n+s.done,0),total:summaries.reduce((n,s)=>n+s.total,0)}}
function card(s){const r=summarize(s,state,period);return `<article class="subject" style="--color:${s.color}"><div class="subject-top"><span class="subject-icon">${s.icon}</span><span class="badge ${r.complete?'green':''}">${r.complete?'Completo':r.done?'En marcha':'Por empezar'}</span></div><h3>${esc(s.name)}</h3><div class="score">${fmt(r.value)} <small>${r.value===null?'Sin notas todavía':'/ 10 · estimación'}</small></div><div class="bar"><i style="width:${r.total?r.done/r.total*100:0}%"></i></div><div class="subject-bottom"><span>${r.done} de ${r.total} criterios</span><span>Abrir ↗</span></div><button data-subject="${s.id}" aria-label="Abrir criterios de ${esc(s.name)}"></button></article>`}
function home(){const a=stats();return `<section class="page-head"><div><span class="eyebrow">UN POCO MÁS CERCA, CADA DÍA</span><h1>Tu curso, en perspectiva<span style="color:#aba1cf">.</span></h1><p>Entiende dónde estás y descubre tu siguiente paso.</p></div><button class="primary" data-nav="subjects">＋ Añadir notas</button></section><section class="hero"><div><span class="eyebrow">MENOS LÍO. MÁS CLARIDAD.</span><h2>${a.done?'Cada criterio cuenta. Tú decides el siguiente paso.':'Tus notas tienen mucho que contarte.'}</h2><p>${a.done?'Explora qué cambiaría al mejorar un criterio y encuentra dónde concentrar tu esfuerzo.':'Añade las valoraciones de tus criterios. Nosotros conectamos los números para que veas cómo vas.'}</p><button class="primary" data-nav="${a.done?'radar':'subjects'}">${a.done?'Explorar mi radar':'Empezar mi cuaderno'} &nbsp;↗</button></div><div class="illustration" aria-hidden="true"><div class="orb"><div class="book">✧</div></div><span class="spark">✦</span></div></section><section class="stats"><div class="stat"><div class="stat-label">Media global estimada <span class="mini-icon">∑</span></div><div class="stat-num">${fmt(a.global)} <span>/ 10</span></div><small>${a.known.length} de ${averaged().length} materias con datos · ATEDU excluida${state.normalized?' · Religión excluida':''}</small></div><div class="stat"><div class="stat-label">Tu mapa de criterios <span class="mini-icon">▦</span></div><div class="stat-num">${a.done} <span>/ ${a.total}</span></div><small>Sin evaluar no significa cero</small></div><div class="stat"><div class="stat-label">Tu próximo paso <span class="mini-icon">↗</span></div><div class="stat-num" style="font-size:23px">${a.done?'Explora tu radar':'Añade una nota'}</div><small>${a.done?'Prueba mejoras sin cambiar tus notas':'Empieza por cualquier asignatura'}</small></div></section><section><div class="section-head"><div><h2>Mis asignaturas</h2><p>Un pequeño mapa de todo lo que estás aprendiendo.</p></div><button class="small outline" data-nav="settings">Personalizar</button></div><div class="grid">${active().map(card).join('')}${state.attention==='atedu'?`<article class="subject" style="--color:#859578"><div class="subject-top"><span class="subject-icon">☀</span><span class="badge">Sin calificación</span></div><h3>Atención Educativa · ATEDU</h3><div class="score" style="font-size:18px">Aprender también es esto</div><small>Seguimiento informativo, fuera de la media.</small><button id="atedu" aria-label="Abrir Atención Educativa"></button></article>`:''}</div></section><section class="two-col"><div class="panel tint"><div class="tip-title"><span>✳</span><h3>Un número no cuenta toda la historia</h3></div><p>Una media con pocos criterios es una primera pista. Mira también cuántos tienes evaluados y qué competencias quedan por conocer.</p><button class="small outline" data-nav="guide">Entender mi cálculo →</button></div><div class="panel"><div class="tip-title"><span style="color:#9483c4">⌁</span><h3>¿Y si subo ese 5 a un 7?</h3></div><p>Haz la prueba. El simulador te enseña el efecto en la asignatura y en tu media global sin tocar tus notas reales.</p><button class="small outline" data-nav="sim">Probar un escenario →</button></div></section>`}
function subjects(){const s=subject();if(!s)return '<div class="panel empty"><h1>Elige tus materias</h1><p>Configura tu cuaderno para empezar.</p><button data-nav="settings">Configurar materias</button></div>';const r=summarize(s,state,period);return `<section class="page-head"><div><span class="eyebrow">CRITERIO A CRITERIO</span><h1>Las piezas de tu nota.</h1><p>Añade tantas valoraciones como tengas para cada criterio. Todas quedan guardadas.</p></div><div class="controls"><button class="outline" id="bulk">Pegar varias notas</button></div></section><div class="toolbar"><select id="subject-select" aria-label="Asignatura">${options(active().map(s=>[s.id,s.name]),selected)}</select><input id="search" type="search" placeholder="Buscar código o palabra…" aria-label="Buscar un criterio" value="${esc(filter)}"><label style="margin:0;display:flex;align-items:center;gap:7px"><input type="checkbox" id="pending" ${onlyPending?'checked':''}> Solo pendientes</label></div><div class="panel"><div class="section-head"><div><h2>${esc(s.name)}</h2><p>${r.done}/${r.total} criterios · ${r.groups.filter(g=>g.value!==null).length}/${r.groups.length} competencias con datos</p></div><div class="stat-num" style="margin:0;color:var(--accent)">${fmt(r.value)} <span>/ 10</span></div></div><small>Estimación mediante ${methodName()}. ${r.complete?'Todos los criterios tienen una valoración.':'Cálculo parcial: se excluyen los criterios y competencias sin datos.'}</small></div><div class="notice">${period==='course'?'Vista del curso: media de todas las notas de cada criterio en las tres evaluaciones. Si hay valoraciones finales confirmadas, se usa su media para ese criterio, conservando el historial.':'Cada criterio admite varias notas: su estimación es la media aritmética de las registradas en esta evaluación. Abre «Notas» para añadir, editar o eliminar valoraciones. No copies la nota global de una actividad si tu docente no la vincula a ese criterio.'} ${s.id==='fr'?'Francés utiliza como referencia Lengua Extranjera; confirma la adaptación de nivel con tu docente.':''}${s.id==='alt'?'MLCT: añade los criterios concretados por tu centro desde Ajustes; esta ficha no tiene un currículo numérico predefinido.':''}</div><div id="criterion-list">${criterionList(s,r)}</div>${sourceNote(s)}`}
function criterionList(s,r){let shown=0;const content=r.groups.map(g=>{const cs=r.values.filter(c=>c.competency===g.id&&(!onlyPending||c.value===null)&&(`${c.code} ${c.text}`.toLocaleLowerCase().includes(filter.toLocaleLowerCase())));shown+=cs.length;if(!cs.length)return '';return `<section class="competency"><div class="competency-head"><h3>Competencia ${g.id}</h3><small>${g.done}/${g.total} criterios &nbsp; <strong>${fmt(g.value)}</strong></small></div>${cs.map(c=>`<div class="criterion"><span class="code">${c.code}</span><details><summary><span class="criterion-text">${esc(c.text)}</span></summary></details><div><div class="criterion-score">${fmt(c.value)}</div><small>${entriesFor(state,s.id,c.code,period).length} notas · ${c.value===null?'sin evaluar':'media / 10'}</small><button class="small outline" data-notes="${c.code}" aria-label="Notas del criterio ${c.code}">＋ Notas</button></div></div>`).join('')}</section>`}).join('');return shown?content:'<div class="empty">No hay criterios que coincidan con tu búsqueda.</div>'}
function radar(){let list=[];for(const s of active()){const r=summarize(s,state,period);if(r.value===null)continue;for(const c of r.values.filter(c=>c.value!==null&&c.value<10)){const next=Math.min(10,c.value+2);const after=summarize(s,state,period,{[c.code]:next});list.push({s,c,before:r.value,after:after.value,gain:after.value-r.value,next,complete:r.complete});}}list.sort((a,b)=>b.gain-a.gain||a.c.value-b.c.value);return `<section class="page-head"><div><span class="eyebrow">DESCUBRE DÓNDE PUEDES AVANZAR</span><h1>Tu radar de mejora.</h1><p>Qué cambiaría al subir hasta 2 puntos en cada criterio conocido.</p></div></section><div class="notice">Ordenamos por impacto matemático en la asignatura, no por dificultad ni importancia educativa. El impacto usa solo los datos disponibles: puede cambiar cuando añadas criterios pendientes.</div>${!list.length?`<div class="panel empty"><div class="symbol">◎</div><h2>${stats().done?'Todo lo registrado está en 10.':'Tu radar empieza con una nota.'}</h2><p>${stats().done?'Añade las valoraciones pendientes para completar tu mapa.':'Añade algún criterio y verás aquí escenarios de mejora concretos.'}</p><button class="primary" data-nav="subjects">Ir a mis criterios</button></div>`:`<div class="grid">${list.slice(0,12).map((x,i)=>`<article class="panel" style="--color:${x.s.color}"><div class="section-head"><span class="subject-icon">${x.s.icon}</span><span class="badge">OPORTUNIDAD ${i+1}</span></div><h3>${esc(x.s.name)}</h3><p style="min-height:38px">Criterio <strong>${x.c.code}</strong> · Competencia ${x.c.competency}</p><div style="font-size:24px;font-weight:650">${fmt(x.c.value)} <span class="muted">→</span> ${fmt(x.next)}</div><div class="bar"><i style="width:${x.next*10}%"></i></div><p>Materia: ${fmt(x.before)} → <strong>${fmt(x.after)}</strong><br><span style="color:var(--green)">+${fmt(x.gain)} puntos estimados</span></p><button class="outline small" data-sim-sub="${x.s.id}" data-sim-code="${x.c.code}" data-sim-value="${x.next}">Explorar escenario ↗</button></article>`).join('')}</div>`}<div class="panel" style="margin-top:22px"><h3>Lo que todavía no sabes también cuenta</h3><p>Antes de perseguir décimas, completa el mapa. Una competencia con un único criterio evaluado puede cambiar bastante al añadir los demás.</p><div class="progress-list">${active().map(s=>{let r=summarize(s,state,period);return `<div class="progress-item"><span style="width:170px">${esc(s.name)}</span><div class="bar"><i style="width:${r.total?r.done/r.total*100:0}%"></i></div><span>${r.done}/${r.total}</span></div>`}).join('')}</div></div>`}
function simulator(){const s=active().find(s=>s.id===simSubject&&s.criteria.length)||active().find(s=>s.criteria.length);if(!s)return '<div class="panel empty"><h1>Prepara tu simulador</h1><p>Selecciona una materia con criterios en Ajustes.</p><button data-nav="settings">Configurar materias</button></div>';if(!s.criteria.some(c=>c.code===simCode))simCode=s.criteria[0]?.code;const before=summarize(s,state,period),c=s.criteria.find(c=>c.code===simCode);const after=c?summarize(s,state,period,{[simCode]:simValue}):before;const all=averaged().map(x=>summarize(x,state,period));const globalBefore=mean(all.map(r=>round(r.value))),globalAfter=mean(averaged().map(x=>x.id===s.id?round(after.value):round(summarize(x,state,period).value)));const target=remainingTarget(s,state,period,simTarget);return `<section class="page-head"><div><span class="eyebrow">UN LABORATORIO PARA TUS NOTAS</span><h1>¿Y si…?</h1><p>Prueba posibilidades. Tus notas reales se quedan como están.</p></div><span class="badge">MODO SIMULACIÓN</span></section><div class="toolbar"><select id="sim-subject" aria-label="Asignatura a simular">${options(active().filter(s=>s.criteria.length).map(s=>[s.id,s.name]),s.id)}</select></div><div class="two-col" style="margin-top:0"><section class="panel"><h2>Mejorar un criterio</h2><p>Elige una valoración hipotética y mira el efecto.</p><label for="sim-code">Criterio</label><select id="sim-code" style="width:100%">${options(s.criteria.map(c=>[c.code,`${c.code} · ${c.text.slice(0,65)}…`]),simCode)}</select><label for="sim-value">Nueva nota: <strong>${fmt(simValue)}</strong> / 10</label><input id="sim-value" type="range" min="0" max="10" step="0.1" value="${simValue}" style="width:100%;accent-color:var(--accent)"><div style="display:flex;justify-content:space-between"><small>0</small><small>Valor actual: ${fmt(c?criterionValue(state,s.id,c.code,period):null)}</small><small>10</small></div><div class="sim-result"><small>Estimación de la asignatura</small><strong>${fmt(before.value)} → ${fmt(after.value)}</strong><p>Media global: ${fmt(globalBefore)} → ${fmt(globalAfter)}</p></div><p>${before.value===null?'Estás simulando la primera nota de esta asignatura.':'La simulación sustituye solo este criterio y recalcula sus medias.'} Los datos pendientes se excluyen; el resultado no es una predicción oficial.</p></section><section class="panel"><h2>Acercarme a un objetivo</h2><p>¿Qué valoración necesitarías en todos los criterios pendientes, manteniendo los conocidos?</p><label for="sim-target">Objetivo en la asignatura (0–10)</label><input id="sim-target" type="number" min="0" max="10" step="0.1" value="${simTarget}" style="width:100%"><div class="sim-result">${!target?'<strong>Mapa completo</strong><p>No quedan criterios pendientes. Prueba a mejorar uno en el panel de al lado.</p>':target.needed>10?`<strong>No basta con los pendientes</strong><p>Incluso con un 10 en todos, la estimación sería ${fmt(target.high)}. Tendrías que mejorar también criterios ya valorados.</p>`:target.needed<=0?'<strong>Objetivo cubierto</strong><p>Con los valores actuales, incluso un 0 en los pendientes mantendría ese objetivo en este modelo.</p>':`<small>La misma valoración en cada pendiente</small><strong>${fmt(target.needed)} / 10</strong><p>En los ${target.count} criterios que faltan. Para alcanzar el objetivo con dos decimales, apunta al menos a ${(Math.ceil(target.needed*100)/100).toLocaleString('es-ES',{minimumFractionDigits:2})}.</p>`}</div><p>Hipótesis: todos los pendientes obtienen la misma nota, los conocidos no cambian y se completa todo el currículo. Método: ${methodName()}.</p></section></div><div class="notice">Nada de lo que pruebes aquí se guarda como calificación. El profesorado valora tu evolución y decide la nota oficial.</div>`}
function guide(){return `<section class="page-head"><div><span class="eyebrow">LOS NÚMEROS, SIN MISTERIOS</span><h1>Así conectamos tus notas.</h1><p>Fuentes oficiales y supuestos de la calculadora, a la vista.</p></div></section><div class="panel"><h2>El método del Néstor Almendros</h2><div class="steps"><div class="step"><b>01</b><h3>Valoración del criterio</h3><p>Registra las valoraciones que comunica tu docente para cada criterio. Brújula estima ese criterio mediante la media aritmética de sus notas, con igual peso. Es un supuesto de seguimiento, no una fórmula de instrumentos impuesta por el BOJA. Una actividad puede evaluar varios criterios: no repartimos ni copiamos su nota automáticamente.</p></div><div class="step"><b>02</b><h3>Media por competencia</h3><p>Los criterios que empiezan por el mismo número pertenecen a la misma competencia: 2.1 y 2.2 pertenecen a la 2. Se promedian con igual valor.</p></div><div class="step"><b>03</b><h3>Media de competencias</h3><p>Se promedian las competencias específicas de la materia, con el mismo valor. El resultado se redondea a dos decimales, no al entero superior.</p></div></div><div class="notice">Ejemplo: competencia 1 con criterios 6, 8 y 10 → 8. Competencia 2 con un criterio 4 → 4. Materia: (8 + 4) ÷ 2 = <strong>6</strong>. Promediar los cuatro criterios daría 7: son métodos distintos.</div><p><strong>Método activo: ${methodName()}.</strong> ${state.method==='criteria'?'Has elegido una alternativa para otros centros. No es el método del PEC 2025 del Néstor Almendros.':'Es el método de referencia del PEC del centro publicado el 12/11/2025, apartado 5.1.4, p. 27.'}</p><h3>Datos incompletos y evaluaciones</h3><p>Un criterio vacío no cuenta como cero. Excluimos criterios sin nota de la media de su competencia y competencias sin datos de la materia. Por eso una nota con 2 de 23 criterios es una estimación parcial. La vista «Curso» reúne todas las notas de las tres evaluaciones de cada criterio y calcula su media (no la media de las medias trimestrales). Si registras valoraciones finales confirmadas, usa su media para ese criterio y conserva las anteriores. Es una convención de seguimiento de esta web, no una fórmula impuesta por el BOJA. No trasladamos automáticamente la nota global de un examen a sus criterios.</p><h3>Media global y nota oficial</h3><p>La media global promedia las estimaciones de las materias que tienen datos, cada una redondeada a centésimas. Muestra su cobertura y excluye ATEDU. No determina la promoción ni sustituye al boletín. El resultado oficial lo decide el profesorado, con la programación de cada departamento.</p><h3>ATEDU y Francés</h3><p>El PEC del centro trata Atención Educativa como seguimiento informativo, sin calificación. Francés usa el currículo de Lengua Extranjera como referencia adaptada al nivel; puedes cambiarlo por Materia Lingüística Transversal en Ajustes y registrar sus criterios concretados por el centro.</p></div><div class="panel" style="margin-top:22px"><h2>Fuentes que puedes comprobar</h2><ul class="source-list"><li><a href="${BOJA}" target="_blank" rel="noopener">BOJA 104, 2 de junio de 2023 · Orden de 30 de mayo</a><br><small>Arts. 10 y 11: criterios y evaluación; art. 14: calificación. Anexos II–III: códigos y textos de 1.º a 4.º ESO. Los saltos de numeración se conservan (por ejemplo, CYR pasa de 2.1 a 2.3).</small></li><li><a href="${PEC}#page=28" target="_blank" rel="noopener">Proyecto educativo del IES Néstor Almendros · 12/11/2025</a><br><small>§5.1.4, p. 27: media de competencias. P. 25: criterios e instrumentos sin ponderaciones. P. 62: ATEDU informativa. Sustituye para esta web la referencia antigua de 2024.</small></li><li><a href="https://www.iesnestoralmendros.es/joomla/principal/plan-de-centro.html" target="_blank" rel="noopener">Plan de Centro · documento publicado por el instituto</a></li><li><a href="https://www.boe.es/diario_boe/txt.php?id=BOE-A-2022-4975" target="_blank" rel="noopener">Real Decreto 217/2022 · Segunda Lengua Extranjera</a><br><small>Referencia para la adaptación de los criterios al nivel del alumnado de segunda lengua.</small></li><li><a href="https://sites.google.com/g.educaand.es/41701183-tecnologiainformatica/programaciones" target="_blank" rel="noopener">Programaciones de Tecnología e Informática del centro</a><br><small>Enlaces a la programación y los criterios de CYR. La media de valoraciones de un criterio es una estimación de esta web; comprueba cómo evalúa tu docente.</small></li></ul><p>Consulta realizada el 29/10/2026. Los textos del BOJA se han extraído de las columnas de cada curso de ESO. No se incorporan adaptaciones individuales. Comprueba siempre los criterios comunicados por tu docente.</p></div>`}
function settings(){return `<section class="page-head"><div><span class="eyebrow">A TU MANERA</span><h1>Tu cuaderno. Tus datos.</h1><p>${state.course}.º ESO · ${esc(state.year)}. Cada curso académico tiene sus propias notas.</p></div><button class="primary" id="new-book">＋ Otro curso académico</button></section><div class="panel"><h2>Mis cuadernos</h2><label for="notebook">Abrir un cuaderno guardado</label><select id="notebook">${options(library.notebooks.map(b=>[b.id,`${b.course}.º ESO · ${b.year}`]),state.id)}</select><div class="settings-row"><div><h3>Método de cálculo</h3><p>Referencia inicial: PEC del Néstor Almendros, noviembre de 2025. Confírmalo con tu centro.</p></div><select id="method">${options([['competencies','Media de competencias · Néstor'],['criteria','Media de criterios']],state.method)}</select></div><div class="settings-row"><div><h3>Atención Educativa o Religión</h3><p>ATEDU es seguimiento informativo. Para Religión, introduce los criterios de tu programación.</p></div><select id="attention">${options([['atedu','Atención Educativa'],['religion','Religión'],['none','Sin selección']],state.attention)}</select></div><label><input type="checkbox" id="normalized" ${state.normalized?'checked':''}> Media global sin Religión (comparación entre expedientes)</label></div><section class="panel" style="margin-top:22px"><h2>Mis materias · ${state.course}.º ESO</h2><p>Catálogo de Andalucía. La oferta concreta depende del centro. Desmarcar una materia conserva sus notas.</p><div class="notice">${state.course===4?'Elige Matemáticas A o B, tres materias de opción y una optativa autonómica.':'Selecciona tus materias comunes y una optativa autonómica.'} ${state.course===1?'Francés y Materia Lingüística Transversal son alternativas según la decisión educativa del centro.':''}</div>${['common','math','choice','optional','custom'].map(kind=>{const list=catalog.filter(s=>(s.kind||'common')===kind&&s.id!=='rel');return list.length?`<h3>${({common:'Comunes',math:'Matemáticas A o B',choice:'Materias de opción',optional:'Optativas autonómicas',custom:'Concreción del centro'})[kind]}</h3><div class="subject-choices">${list.map(s=>`<label><input type="checkbox" data-choice="${s.id}" ${state.selectedSubjects.includes(s.id)?'checked':''}> ${esc(s.name)}</label>`).join('')}</div>`:''}).join('')}<p>${active().length} materias seleccionadas. Comprueba tu matrícula antes de introducir notas.</p><button class="outline" id="new-subject">＋ Materia del centro</button><h3>Criterios propios del centro</h3><p>MLCT, proyectos y Religión requieren los códigos y textos que comunique el docente. No inventamos criterios.</p>${active().filter(s=>s.custom).map(s=>`<p>${esc(s.name)} · ${s.criteria.length} criterios <button class="small outline" data-custom="${s.id}">Añadir criterio</button></p>`).join('')}</section><div class="two-col"><section class="panel"><h2>Una copia que viaja contigo</h2><p>Exporta todos tus cuadernos para llevarlos a otro navegador, dispositivo o a la nueva dirección de GitHub Pages. Los datos locales no viajan automáticamente al cambiar de web.</p><button class="primary" id="export">↓ Exportar copia</button> <button class="outline" id="import">↑ Importar copia</button><input type="file" id="file" accept=".json,application/json" hidden><p>Importar sustituye todos los cuadernos tras confirmar. Guarda antes una copia.</p></section><section class="panel"><h2>Compartir Brújula</h2><p>El enlace comparte la herramienta. Cada navegador guarda sus propios datos, sin cuenta.</p><button class="outline" id="share">Copiar enlace</button><p><a href="./assets/social1200x630.png" download>Imagen para redes</a> · <a href="./assets/social-square1080.png" download>Cuadrada</a> · <a href="./assets/story1080x1920.png" download>Historia</a></p><a href="./fuentes.html">Fuentes, método y privacidad ↗</a></section></div><section class="panel" style="margin-top:22px"><h3>Vaciar este cuaderno</h3><p>Borra únicamente las notas y el seguimiento de ${state.course}.º ESO · ${esc(state.year)}. Conserva las materias y los demás cuadernos.</p><button class="outline danger" id="reset">Borrar notas de este cuaderno</button></section>`}
function bindSettings(){
 $('#course').onchange=e=>switchBook(Number(e.target.value),state.year);
 $('#notebook')?.addEventListener('change',e=>{library.activeId=e.target.value;syncBook();save();render()});
 $('#attention')?.addEventListener('change',e=>{state.attention=e.target.value;toggleSubject(state,'rel',state.attention==='religion');save();render()});
 $('#normalized')?.addEventListener('change',e=>{state.normalized=e.target.checked;save();render()});
 document.querySelectorAll('[data-choice]').forEach(el=>el.onchange=()=>{toggleSubject(state,el.dataset.choice,el.checked);save();render()});
 $('#new-book')?.addEventListener('click',()=>{modal(`<h2>Otro curso académico</h2><p>Se abrirá un cuaderno independiente; los anteriores se conservan.</p><label>Año académico<input id="book-year" value="${state.year}" placeholder="2027/28"></label><label>Curso<select id="book-course">${options([1,2,3,4].map(n=>[String(n),`${n}.º ESO`]),String(state.course))}</select></label><div class="actions"><button data-close>Cancelar</button><button class="primary" id="book-open">Abrir cuaderno</button></div>`);$('#book-open').onclick=()=>{try{switchBook(Number($('#book-course').value),$('#book-year').value);$('#modal').close()}catch(e){toast(e.message)}}});
 $('#new-subject')?.addEventListener('click',()=>{modal('<h2>Materia del centro</h2><label>Nombre<input id="custom-name" maxlength="120"></label><div class="actions"><button data-close>Cancelar</button><button class="primary" id="subject-create">Crear materia</button></div>');$('#subject-create').onclick=()=>{const name=$('#custom-name').value.trim();if(!name)return toast('Escribe el nombre de la materia');if(state.customSubjects.length>=30)return toast('Máximo de 30 materias propias');const id='custom-'+crypto.randomUUID();state.customSubjects.push({id,name,course:state.course,custom:true,kind:'custom',criteria:[],pages:[],color:'#9083b0',icon:'✧'});toggleSubject(state,id,true);syncBook();save();$('#modal').close();render()}});
 document.querySelectorAll('[data-custom]').forEach(el=>el.onclick=()=>addCustom(el.dataset.custom));
}
function sourceNote(s){if(s.custom)return '<p class="notice">Criterios aportados por el usuario desde la programación del centro. No son una transcripción automática del BOJA.</p>';const page=Number(s.pages[0]||1),part=page>289?'BOJA23-104-00246-9727-02_00284752.pdf':'BOJA23-104-00289-9727-01_00284752.pdf';return `<p><small>${s.reference?'Referencia de Lengua Extranjera: requiere adaptación docente. ':''}BOJA · ${state.course}.º ESO · páginas ${s.pages.join(', ')}. <a href="https://www.juntadeandalucia.es/boja/2023/104/${part}#page=${page>289?page-289:page}" target="_blank" rel="noopener">Abrir texto original ↗</a> · <a href="./fuentes.html">Fuentes y límites</a></small></p>`}
function render(){if(!active().some(s=>s.id===selected))selected=active()[0]?.id;$('#app').innerHTML=frame(({home,subjects,radar,sim:simulator,guide,settings})[view]());bind();bindSettings()}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close())}
function setGrade(code,value,p=period){appendGrade(state,selected,code,p,value,'',localDate())}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>navigate('subjects',b.dataset.subject));$('#period').onchange=e=>{period=e.target.value;render()};$('#subject-select')?.addEventListener('change',e=>{selected=e.target.value;filter='';render()});$('#search')?.addEventListener('input',e=>{filter=e.target.value;$('#criterion-list').innerHTML=criterionList(subject(),summarize(subject(),state,period));bindGrades()});$('#pending')?.addEventListener('change',e=>{onlyPending=e.target.checked;render()});bindGrades();$('#bulk')?.addEventListener('click',bulkModal);$('#edit-period')?.addEventListener('click',()=>{period='1';render()});$('#atedu')?.addEventListener('click',()=>{modal(`<h2>Atención Educativa</h2><p>El PEC del Néstor Almendros la considera informativa y no evaluable. No se incluye en tu media.</p><label for="reflection">Tu seguimiento personal (opcional)</label><textarea id="reflection" rows="6" maxlength="10000" style="width:100%" placeholder="Algo que has aprendido o quieres recordar…">${esc(state.atedu)}</textarea><div class="actions"><button data-close>Cancelar</button><button class="primary" id="save-reflection">Guardar</button></div>`);$('#save-reflection').onclick=()=>{state.atedu=$('#reflection').value;save();$('#modal').close();toast('Seguimiento guardado en este navegador')}});document.querySelectorAll('[data-sim-sub]').forEach(b=>b.onclick=()=>{simSubject=b.dataset.simSub;simCode=b.dataset.simCode;simValue=Number(b.dataset.simValue);navigate('sim')});$('#sim-subject')?.addEventListener('change',e=>{simSubject=e.target.value;render()});$('#sim-code')?.addEventListener('change',e=>{simCode=e.target.value;render()});$('#sim-value')?.addEventListener('change',e=>{simValue=Number(e.target.value);render()});$('#sim-target')?.addEventListener('change',e=>{let n=Number(e.target.value);if(e.target.value===''||!Number.isFinite(n)||n<0||n>10){toast('El objetivo debe estar entre 0 y 10');e.target.value=simTarget;return}simTarget=n;render()});$('#year')?.addEventListener('change',e=>{state.year=e.target.value.trim()||'2026/27';save();render()});$('#language')?.addEventListener('change',e=>{state.language=e.target.value;save();render()});$('#method')?.addEventListener('change',e=>{state.method=e.target.value;save();render()});$('#export')?.addEventListener('click',exportData);$('#import')?.addEventListener('click',()=>$('#file').click());$('#file')?.addEventListener('change',importData);$('#share')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.origin+location.pathname);toast('Enlace copiado. Tus notas no se comparten.')}catch{modal(`<h2>Enlace para compartir</h2><input readonly style="width:100%" value="${esc(location.origin+location.pathname)}"><div class="actions"><button data-close>Cerrar</button></div>`)}});$('#reset')?.addEventListener('click',()=>{modal('<h2>¿Borrar este cuaderno?</h2><p>Se eliminarán todas las notas y el seguimiento de ATEDU de este navegador. Esta acción no se puede deshacer sin una copia.</p><div class="actions"><button data-close>Cancelar</button><button class="primary" id="confirm-reset">Sí, borrar mis datos</button></div>');$('#confirm-reset').onclick=()=>{state.grades={};state.atedu='';save();$('#modal').close();render();toast('Cuaderno vacío. Listo para empezar.')}});}
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function bindGrades(){document.querySelectorAll('[data-notes]').forEach(b=>b.onclick=()=>notesModal(b.dataset.notes))}
function notesModal(code){
 const s=subject(),draft=['1','2','3','final'].flatMap(p=>entriesFor(state,s.id,code,p));
 const defaultPeriod=period==='course'?'1':period;
 function row(e,i){return `<fieldset class="note-row" data-entry="${esc(e.id)}"><legend>Valoración ${i+1}</legend><label>Nota<input data-value inputmode="decimal" aria-label="Nota ${i+1}" value="${e.value===null?'':String(e.value).replace('.',',')}" placeholder="0–10"></label><label>Actividad (opcional)<input data-label maxlength="150" value="${esc(e.label)}" placeholder="Ej.: prueba de fracciones"></label><label>Evaluación<select data-period>${options(periods.filter(([p])=>p!=='course'),e.period)}</select></label><label>Fecha (opcional)<input data-date type="date" value="${esc(e.date)}"></label><button type="button" class="small danger" data-remove aria-label="Quitar valoración ${i+1}">Quitar</button></fieldset>`}
 modal(`<h2>Notas del criterio ${esc(code)}</h2><p>${esc(s.name)} · ${esc(s.criteria.find(c=>c.code===code).text)}</p><div class="notice">Cada nueva nota se añade al historial. Calculamos su media con igual peso dentro de cada criterio. «Final» sirve para una valoración confirmada por tu docente y tiene prioridad en la vista Curso.</div><div id="note-rows">${draft.map(row).join('')}</div><button id="note-add" class="outline">＋ Añadir valoración</button><p id="note-error" role="alert"></p><div class="actions"><button data-close>Cancelar</button><button class="primary" id="notes-save">Guardar valoraciones</button></div>`);
 $('#modal').classList.add('notes-dialog');$('#modal').addEventListener('close',()=>$('#modal').classList.remove('notes-dialog'),{once:true});
 let count=draft.length;
 const bindRemove=()=>document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{b.closest('.note-row').remove()});
 const add=()=>{if(document.querySelectorAll('.note-row').length>=500)return toast('Máximo de 500 valoraciones en el editor.');$('#note-rows').insertAdjacentHTML('beforeend',row({id:crypto.randomUUID(),value:null,label:'',date:localDate(),period:defaultPeriod},count++));bindRemove();$('#note-rows').lastElementChild.querySelector('[data-value]').focus()};
 bindRemove();$('#note-add').onclick=add;if(!draft.length)add();
 $('#notes-save').onclick=()=>{try{const values={};for(const el of document.querySelectorAll('.note-row')){const raw=el.querySelector('[data-value]').value.trim(),value=Number(raw.replace(',','.'));if(!/^\d{1,2}([.,]\d{1,4})?$/.test(raw)||!Number.isFinite(value)||value<0||value>10){el.querySelector('[data-value]').focus();throw Error('Completa cada nota con un número de 0 a 10, o quita la fila vacía.')}const p=el.querySelector('[data-period]').value;(values[p]??=[]).push({id:el.dataset.entry,value,label:el.querySelector('[data-label]').value.trim(),date:el.querySelector('[data-date]').value})}const candidate=structuredClone(library),book=candidate.notebooks.find(b=>b.id===state.id);book.grades[selected]??={};book.grades[selected][code]=values;library=validateLibrary(candidate,allCatalog);syncBook();const saved=save();$('#modal').close();render();if(saved)toast('Valoraciones guardadas · media actualizada')}catch(e){$('#note-error').textContent=e.message}};
}
function bulkModal(){modal(`<h2>Pegar varias valoraciones</h2><p>${esc(subject().name)}. Una línea por valoración (puedes repetir el código): <strong>1.1: 7,5</strong>. Puedes separar líneas con punto y coma.</p><label for="bulk-period">Guardar en</label><select id="bulk-period">${options(periods.filter(([p])=>p!=='course'),period==='course'?'1':period)}</select><label for="bulk-text">Códigos y notas</label><textarea id="bulk-text" rows="7" style="width:100%" placeholder="1.1: 7,5&#10;1.2: 8&#10;2.1: 6"></textarea><div id="bulk-preview" role="status"></div><div class="actions"><button data-close>Cancelar</button><button class="primary" id="bulk-check">Revisar antes de guardar</button></div>`);$('#bulk-check').onclick=()=>{try{const rows=parseBulk($('#bulk-text').value,subject()),p=$('#bulk-period').value;$('#bulk-preview').innerHTML=`<div class="notice">${rows.map(r=>`${r.code} → ${fmt(r.value)}`).join(' · ')}<br>Se añadirán ${rows.length} notas en ${esc(periods.find(x=>x[0]===p)[1])}. Las notas anteriores se conservarán.</div><button class="primary" id="bulk-save">Confirmar estas ${rows.length} notas</button>`;$('#bulk-save').onclick=()=>{const backup=structuredClone(state.grades);try{for(const r of rows)setGrade(r.code,r.value,p)}catch(e){state.grades=backup;toast(e.message);return}save();period=p;$('#modal').close();render();toast('Valoraciones guardadas')}}catch(e){$('#bulk-preview').textContent=e.message}};$('#bulk-text').oninput=()=>$('#bulk-preview').innerHTML='';$('#bulk-period').onchange=()=>$('#bulk-preview').innerHTML=''}
function exportData(){const blob=new Blob([JSON.stringify(library,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='brujula-cuadernos.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia preparada')}
async function importData(e){const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('El archivo supera los 5 MB');const raw=JSON.parse(await file.text()),valid=raw.version===1?migrateV1(raw,allCatalog):validateLibrary(raw,allCatalog);modal(`<h2>Importar ${valid.notebooks.length} cuaderno(s)</h2><p>Esta copia reemplazará todos los cuadernos de este navegador. Exporta antes si quieres conservarlos.</p><div class="actions"><button data-close>Cancelar</button><button class="primary" id="confirm-import">Reemplazar e importar</button></div>`);$('#confirm-import').onclick=()=>{library=valid;loadFailed=false;syncBook();save();$('#modal').close();render();toast('Copia importada')}}catch(err){toast('No se ha importado: '+err.message)}finally{e.target.value=''}}
function addCustom(id){modal('<h2>Añadir criterio del centro</h2><p>Copia el código y texto de tu programación. El primer número identifica la competencia.</p><label>Código<input id="custom-code" placeholder="1.1"></label><label>Descripción<textarea id="custom-text" maxlength="2000" style="width:100%"></textarea></label><div class="actions"><button data-close>Cancelar</button><button class="primary" id="custom-save">Añadir</button></div>');$('#custom-save').onclick=()=>{try{const s=catalog.find(s=>s.id===id),criteria=validCustom([...s.criteria,{code:$('#custom-code').value.trim(),text:$('#custom-text').value.trim()}]);let local=state.customSubjects.find(s=>s.id===id);if(!local){local={...s};state.customSubjects.push(local)}local.criteria=criteria;syncBook();save();$('#modal').close();render()}catch(e){toast(e.message)}}}
async function init(){try{const response=await fetch('./curriculum.json');const styled=await (window.stylesReady||Promise.resolve(true));if(!styled)throw Error('No se pudieron cargar los estilos');await Promise.race([Promise.all([document.fonts.load('500 14px "DM Sans"'),document.fonts.load('700 24px Manrope')]),new Promise(resolve=>setTimeout(resolve,600))]);if(!response.ok)throw Error('Catálogo no disponible');allCatalog=await response.json();const book=createNotebook(1,'2026/27',allCatalog);library={version:3,activeId:book.id,notebooks:[book]};try{const saved=localStorage.getItem(KEY)||localStorage.getItem('brujula-eso-v2'),old=localStorage.getItem('brujula-eso-v1');if(saved)library=validateLibrary(JSON.parse(saved),allCatalog);else if(old)library=migrateV1(JSON.parse(old),allCatalog,JSON.parse(localStorage.getItem('brujula-eso-v1-custom')||'[]'))}catch(e){storageError=true;loadFailed=true}syncBook();render()}catch(e){$('#app').innerHTML='<main class="panel" style="margin:30px"><h1>No se ha podido abrir el cuaderno.</h1><p>Recarga la página cuando tengas conexión. Tus datos locales no se han borrado.</p></main>';console.error(e)}finally{window.finishBoot?.()}}
window.addEventListener('storage',e=>{if(e.key===KEY)toast('El cuaderno ha cambiado en otra pestaña. Recarga antes de seguir editando.')});init();
